using Godot;
using System;
using System.Linq;
public partial class MigrationScene {
 static readonly string[][] ResidentNames={new[]{"Iris","Mal","Jules","Tessa"},new[]{"Gus","Nia","Rafi","Len"},new[]{"Ada","Rook","June","Eli"},new[]{"Voss","Mercer","Rhea","Kane"}};
 PersonalStanding Standing(string person)=>game.World.Changes.Standing(CommunityOwner,person);
 void RememberTown(int index,int delta,string memory){var w=game.World.Changes;w.Remember(CommunityOwner,"town/"+index,delta,memory);for(int j=0;j<4;j++)w.Remember(CommunityOwner,$"resident/{index}/{j}",delta+(j==1&&delta>0?1:0),memory);}
 void ShowRelationships(){var b=Panel("PEOPLE REMEMBER / YOUR REPUTATION");var scroll=new ScrollContainer{CustomMinimumSize=new(880,430)};b.AddChild(scroll);var rows=new VBoxContainer();scroll.AddChild(rows);void Row(string label,string id){var r=Standing(id);Text(rows,$"{label} / {r.Rank} ({r.Value})\n{r.Memory}");}
  foreach(var t in game.World.Changes.Settlements.Where(t=>t.Visits>0)){Row(ExpeditionGame.SettlementNames[t.Index],"town/"+t.Index);for(int j=0;j<4;j++){int resident=j,town=t.Index;Row("  "+ResidentNames[town][j],$"resident/{town}/{j}");Button(rows,"TALK / "+ResidentNames[town][j],()=>ShowResident(town,resident));}}
  if(Community.Established)Row("Your settlement","home");foreach(var n in Community.Survivors.Where(n=>n.State!="trapped"))Row(n.Name,n.Id);if(Dog.Rescued)Text(rows,(Dog.Name==""?"Your dog":Dog.Name)+$" / Bond {Dog.Bond:0} / "+(Dog.Dead?"Lost forever":"Learning to trust you"));Button(b,"BACK",()=>ShowCommunity());
 }
 void ShowResident(int town,int resident){var r=Standing($"resident/{town}/{resident}");var b=Panel(ResidentNames[town][resident]+" / "+r.Rank);Text(b,r.Memory+"\n"+(r.Value<0?"They keep their distance and refuse personal favors.":r.Value>=20?"They trust you enough to share their own provisions.":"Trust comes from returning with help, not introductions."));void Act(string text,string op){Button(b,text,()=>{string data=town+"|person:"+resident+":"+op;if(!CoopRequest("living",data))LivingAction(data);});}Act("SHARE A MEAL / 1 FOOD","meal");Act("ASK FOR A PERSONAL FAVOR / TRUSTED ONLY","favor");Text(b,"Stand at this community to act. Each person remembers separately; meal/favor cooldown is 10 active minutes.");Button(b,"BACK",ShowRelationships);}
 bool ResidentAction(int index,string op){if(!op.StartsWith("person:"))return false;var p=op.Split(':');if(p.Length!=3||!int.TryParse(p[1],out int j)||j<0||j>3)return true;var r=Standing($"resident/{index}/{j}");if(game.World.Changes.Time<r.GiftAt){game.Notice="Give them time / ten active minutes between personal favors";return true;}if(p[2]=="meal"&&game.Life.Food>0)game.Change(()=>{game.Life.Food--;game.World.Changes.Remember(CommunityOwner,$"resident/{index}/{j}",5,"You sat with me and shared your food.");r.GiftAt=game.World.Changes.Time+600;});else if(p[2]=="favor"&&r.Value>=20&&Town(index).Trust>=0&&!(index==2&&Fever.CitySeen&&!Fever.Redemption)&&Town(index).Food>2)game.Change(()=>{Town(index).Food--;game.Life.Food++;r.GiftAt=game.World.Changes.Time+600;r.Memory="I gave you my ration. Please remember us.";});else game.Notice="They cannot offer that / check trust and supplies";game.Persist();return true;}
}
